/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    normalizeBattleHistorySaveEntry
 * depends    —
 * used by    src/mechanics/calculators/specs-generated, src/save/battle-reports, src/save/index
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
function hasSaveValue(value: unknown): boolean {
  if (value == null) return false
  if (typeof value === 'number') return Number.isFinite(value)
  return String(value).trim().length > 0
}

function copyFirstPresentSaveValue(
  target: Record<string, unknown>,
  canonicalKey: string,
  sourceKeys: readonly string[],
): void {
  if (hasSaveValue(target[canonicalKey])) return
  for (const sourceKey of sourceKeys) {
    const value = target[sourceKey]
    if (!hasSaveValue(value)) continue
    target[canonicalKey] = value
    return
  }
}

/**
 * Normalize a raw battle-history save entry onto the canonical stitched-run key
 * shape used locally before cloud split. Handles legacy flat keys and *ThisRound
 * snapshot keys from newer game builds.
 */
export function normalizeBattleHistorySaveEntry(entry: Record<string, unknown>): Record<string, unknown> {
  const normalized: Record<string, unknown> = { ...entry }

  const mappings: Array<[canonicalKey: string, sourceKeys: readonly string[]]> = [
    ['realTime', ['realTimeThisRound', 'gameplayTimeThisRound']],
    ['coinsEarned', ['coinsEarnedThisRound']],
    ['cellsEarned', ['cellsEarnedThisRound']],
    ['rerollShardsEarned', ['rerollCurrencyEarnedThisRound']],
    ['totalEnemies', ['totalEnemiesDestroyedThisRound']],
    ['destroyedInSpotlight', ['enemiesDestroyedInSpotlightThisRound']],
    ['taggedByDeathwave', ['totalEnemiesTaggedByDeathwaveThisRound']],
    ['orbHits', ['orbHitsThisRound']],
    ['destroyedByOrbs', ['enemiesDestryoedByOrbsThisRound', 'enemiesDestroyedByOrbsThisRound']],
    ['enemiesKilledInGoldenBot', ['enemiesKilledInGoldenBotThisRound']],
    ['guardianSummoned', ['totalSummonedByGuardianThisRound']],
    ['deathDefy', ['deathDefyThisRound']],
    ['wavesSkipped', ['wavesSkippedThisRound']],
    ['recoveryPackages', ['recoveryPackagesThisRound']],
    ['projectilesCount', ['projectilesFiredThisRound']],
    ['damageDealt', ['damageDealtThisRound']],
    ['freeAttackUpgrades', ['freeAttackUpgradesThisRound']],
    ['freeDefenseUpgrades', ['freeDefenseUpgradesThisRound']],
    ['freeUtilityUpgrades', ['freeUtilityUpgradesThisRound']],
  ]

  for (const [canonicalKey, sourceKeys] of mappings) {
    copyFirstPresentSaveValue(normalized, canonicalKey, sourceKeys)
  }

  return normalized
}
